const input = $input.first()?.json ?? {};
const body = input.body ?? input;
const headers = input.headers ?? {};
const rawPayload = body.payload ?? input.payload ?? {};
let payload = rawPayload;
if (typeof rawPayload === 'string') { try { payload = JSON.parse(rawPayload); } catch (e) { payload = {}; } }
return [{ json: { action: String(body.action || input.action || '').trim(), payload, authorization: String(headers.authorization || headers.Authorization || input.authorization || '').trim(), request_id: String(headers['x-request-id'] || headers['X-Request-Id'] || input.request_id || ('req-' + Date.now())), actor_email: String(headers['x-actor-email'] || headers['X-Actor-Email'] || input.actor_email || ''), received_at: new Date().toISOString() } }];

const expected = String($env.ADMIN_BACKOFFICE_TOKEN || 'REPLACE_ME').trim();
const token = String($json.authorization || '').replace(/^Bearer\s+/i, '').trim();
return [{ json: { ...$json, auth_ok: Boolean(expected && token && token === expected) } }];

const rows = Array.isArray($json) ? $json : Array.isArray($json.data) ? $json.data : Array.isArray($json.body) ? $json.body : [];
const row = rows[0] || null;
const root = $('Get Pack For Zoho Send').first().json;
const request = $('If Send Payload Valid').all().length ? $('If Send Payload Valid').first().json : $('If Approve And Send Mode').first().json;
return [{ json: { ...request, pack_row: row, found: Boolean(row) } }];

function safeFileStem(value) { return String(value || 'Prospect').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-zA-Z0-9]+/g, '_').replace(/^_+|_+$/g, '') || 'Prospect'; }
const row = $json.pack_row || {};
const payload = row.payload || {};
const rawAttachments = Array.isArray(payload.mail_attachments) ? payload.mail_attachments : [];
let catalogueUrl = payload.catalogue_artifact?.pdf_url || null;
let deckUrl = payload.deck_artifact?.pptx_url || null;
for (const att of rawAttachments) { const name = String(att.filename || ''); if (!catalogueUrl && /\.pdf$/i.test(name) && att.path) catalogueUrl = att.path; if (!deckUrl && /\.pptx$/i.test(name) && att.path) deckUrl = att.path; }
const org = safeFileStem(row.organization_name || payload.organization_name || 'Prospect');
const targetEmail = row.target_email || payload.target_email || null;
const executiveLetterHtml = payload.executive_letter_html || String(payload.executive_letter || '').replace(/\n/g, '<br>');
const bookingLink = payload.booking_link_45min || $env.BOOKING_LINK_45MIN || 'https://calendly.com/contact-transferai/30min';
const auditFormUrl = payload.audit_form_url || '';
const attachments = []; if (catalogueUrl) attachments.push({ filename: payload.catalogue_artifact?.filename_pdf || ('Mini_Catalogue_TransferAI_' + org + '.pdf'), path: catalogueUrl, outputPropertyName: 'catalogue_pdf' }); if (deckUrl) attachments.push({ filename: payload.deck_artifact?.filename_pptx || ('Deck_TransferAI_' + org + '.pptx'), path: deckUrl, outputPropertyName: 'deck_pptx' });
const canSend = Boolean(targetEmail && executiveLetterHtml && attachments.length >= 2 && catalogueUrl && deckUrl);
const reason = canSend ? null : 'Pack incomplet pour envoi Zoho: email cible, courrier, PDF ou PPTX manquant.';
return [{ json: { ...$json, pack_id: row.pack_id || payload.pack_id || null, prospect_id: row.prospect_id || payload.prospect_id || null, organization_name: row.organization_name || payload.organization_name || null, target_email: targetEmail, reviewer_email: $json.payload?.reviewer_email || null, provider_key: $json.payload?.provider_key || 'zoho-primary', attachments, attachments_count: attachments.length, can_send: canSend, send_failure_reason: reason, subject: "Proposition d'audit gratuit, d'accompagnement et de formation", html: '<p>Madame, Monsieur,</p><p>' + executiveLetterHtml + '</p>' + (auditFormUrl ? '<p>Formulaire d'audit préalable : <a href= + auditFormUrl + >' + auditFormUrl + '</a></p>' : '') + '<p>Réservation : <a href= + bookingLink + >' + bookingLink + '</a></p><p>Cordialement,<br>TransferAI</p>' } }];

const ctx = $('Build Zoho Send Context').first().json;
const merged = $input.first()?.binary ? JSON.parse(JSON.stringify($input.first())) : { binary: {} };
const catalogue = $('Download Zoho Catalogue PDF').first();
const deck = $('Download Zoho Deck PPTX').first();
const binary = Object.assign({}, (catalogue && catalogue.binary) || {}, (deck && deck.binary) || {}, merged.binary || {});
return [{ json: { ...ctx }, binary }];

const root = $('Build Zoho Send Context').first().json;
const action = String(root.action || '') === 'approve_pack' ? 'approve_and_send_pack' : 'send_pack';
return [{ json: { ok: true, action, status: 'sent', message: 'Pack envoye via Zoho SMTP.', data: { pack_id: root.pack_id, provider_key: root.provider_key || 'zoho-primary', provider_name: 'zoho-smtp', provider_message_id: null, sent_at: new Date().toISOString() }, meta: { request_id: root.request_id, timestamp: new Date().toISOString() } } }];
